INSERT INTO public.products (id, store_id, shipstation_product_id, sku, name, slug, short_description, long_description, description_html, base_price, sale_price, cost_price, track_inventory, stock_quantity, low_stock_threshold, allow_backorder, weight, weight_unit, length, width, height, dimension_unit, category_id, tags, featured_image_url, gallery_images, meta_title, meta_description, requires_shipping, shipping_class, is_active, is_featured, is_digital, override_name, override_description, override_price, override_images, discount_type, discount_value, created_at, updated_at, published_at, barcode, hs_code, hs_code_description, hs_code_confidence, hs_code_generated_at, vendor, product_type, status, archived_at, publish_at, reorder_point, reorder_quantity, lead_time_days, safety_stock, supplier_id, country_of_origin, completeness_score, field_locks) VALUES ('b9a6f95a-9435-4847-b9dd-adb61be66d7f', '650e8400-e29b-41d4-a716-446655440003', NULL, 'IFT-ACC-3012', 'Thresh Doorway Pull-Up Bar', 'thresh-pull-up-bar', 'A no-screw doorway pull-up bar rated for 300 lbs, that comes down in ten seconds when you''re done.', 'Thresh wedges into a standard doorframe using leverage, not screws, so it comes down in ten seconds and doesn''t leave holes in a rental apartment''s trim.
